'use strict';
/* =====================================================================
   personas.js - the voice the app talks in.

   Every message, hint, toast, empty state and piece of help text is
   written once more for each persona. The plain wording is "Stiff", the
   default, and lives in the normal word tables; each persona here only
   holds its own version of the same keys, so anything it leaves out falls
   back to Stiff. Figures, names and the buttons you press stay the same
   in every voice: only how things are said changes.

   t() asks PERSONA_WORDS first (see ultimate-budget.js), so the switch is
   instant and nothing else needs to know which persona is chosen.
   ===================================================================== */

const PERSONAS = [
  { id: 'stiff', name: 'Stiff', blurb: 'Plain and informative. How it reads by default.',
    sample: 'Your period has ended {0} over budget.' },
  { id: 'dramatic', name: 'Dramatic Storyteller', blurb: 'Every budget period is an epic tale.',
    sample: 'The sands of time have run out on this period, leaving you {0} deep in the budgeting abyss.' },
  { id: 'cheeky', name: 'Cheeky', blurb: 'Playful, with a wink and a nudge.',
    sample: 'The clock hit zero, and unfortunately, you overshot the runway. You are wrapping up this period {0} in the red!' },
  { id: 'sarcastic', name: 'Sarcastic', blurb: 'Dry, and very hard to impress.',
    sample: 'Time is up. You blew past your budget by {0}. Maybe try saying no to things next month.' },
  { id: 'rude', name: 'Rude', blurb: 'Blunt to the point of rude.',
    sample: 'Zero days left and you are {0} over budget. Are you even trying?' },
  { id: 'concise', name: 'Concise', blurb: 'Just the facts, nothing more.',
    sample: 'Period ended. You are {0} over budget.' },
  { id: 'zen', name: 'Zen Master', blurb: 'Calm, whatever the numbers say.',
    sample: 'The cycle concludes. You have flowed {0} beyond your original intentions, but peace remains.' },
  { id: 'optimist', name: 'Optimist', blurb: 'Always looking on the bright side.',
    sample: 'The period is a wrap! You ended up {0} over budget, but tomorrow is a completely fresh start.' }
];
const PERSONA_IDS = PERSONAS.map(p => p.id);
function personaNow() {
  const p = (typeof state !== 'undefined' && state && state.settings && state.settings.persona) || 'stiff';
  return PERSONA_IDS.includes(p) ? p : 'stiff';
}

// ── Settings: choosing a persona ─────────────────────────────────────
function personaCardHtml() {
  const cur = personaNow();
  return `<div class="panel"><div class="panel-inner">
    <div class="settings-card-title">🎭 ${esc(t('persona_title'))}</div>
    <p class="settings-desc">${esc(t('persona_desc'))}</p>
    <div class="persona-grid" role="radiogroup" aria-label="${esc(t('persona_title'))}">${PERSONAS.map(p => `
      <button class="persona-opt${p.id === cur ? ' is-active' : ''}" type="button" role="radio" aria-checked="${p.id === cur}" data-persona="${p.id}">
        <span class="persona-name">${esc(p.name)}</span>
      </button>`).join('')}
    </div>
  </div></div>`;
}
function personaWireCard(el) {
  el.querySelectorAll('[data-persona]').forEach(btn => btn.addEventListener('click', () => {
    const id = btn.dataset.persona;
    if (!PERSONA_IDS.includes(id) || id === personaNow()) return;
    state.settings.persona = id;
    saveState();
    try { trackEvent('persona_changed', { persona: id }); } catch (e) {}
    // Everything on screen is redrawn in the new voice.
    applyLanguage();
    switchTab(currentTab);
    const now = document.querySelector(`[data-persona="${id}"]`);
    if (now) { now.scrollIntoView({ block: 'center' }); now.focus(); }
    showToast(t('toast_persona'));
  }));
}

const PERSONA_BASE_WORDS = {
  persona_title: 'Persona',
  persona_desc: 'How the app talks to you. Your figures and the buttons stay exactly the same; only the voice changes.',
  toast_persona: 'Persona updated'
};
(function personaAddWords() {
  try { Object.assign(TRANSLATIONS.en, PERSONA_BASE_WORDS); } catch (e) {}
})();

