    dash_no_sinking: "No savings quests have begun.",
    help_dash_intro: "The Dashboard lays your entire financial realm before you, live. Every figure shifts as you record transactions.",
    help_dash_hero_p: "The great figure is what you may yet spend this period: all that came in, less all that went out, less all still owed before the period ends. Beside it, Coming up names the next five payments owed, overdue bills first. Press Pay on any to record it.",
    help_dash_leftover_p: "White means you hold your course. Red means what you owe outweighs what remains.",
    help_dash_cashflow_p: "Each row sets Expected (grey bar) against Actual (coloured bar) for Income, Expenses, Bills and Savings. A red Expenses bar means your spending breached the budget.",
