    ch_desc: "Small games for the fateful moment before you spend. When the money triumphs, what you would have spent goes to a goal or a debt instead.",
    ch_cat_decide_desc: "Torn between two paths? Let a game decide, and let your savings triumph.",
    ch_hist_empty: "No game has yet been played. Every outcome shall be recorded here.",
    ch_cf_desc: "Torn between spending and saving? Let fate's coin decide. Heads, you forgo it and the money goes to a goal or debt. Tails, enjoy it, guilt free.",
    ch_step_what: "What temptation calls to you?",
    ch_step_cost: "What would it cost you?",
    ch_cat_fun_desc: "Set aside spending free of guilt, and let the rest toil for you.",
    ch_sc_desc: "A weekend of revelry ahead? Name the most you would gladly spend, then scratch the card. It reveals how much is yours to enjoy, free of guilt. The rest goes to a goal or debt.",
    ch_sc_hint: "Scratch away the silver to reveal your fortune",
