    dash_no_sinking: "No savings goals yet. Dream a little!",
    help_dash_intro: "The Dashboard is your live money overview. Every number updates as you log transactions.",
    help_dash_hero_p: "The big number is what you can still spend this period: money in, minus money out, minus everything still owed before the period ends. Next to it, Coming up shows the next five payments owed, overdue bills first. Hit Pay on any to log it.",
    help_dash_leftover_p: "White means you're on track. Red means you owe more than you've got left.",
    help_dash_cashflow_p: "Each row shows Expected (grey bar) vs Actual (coloured bar) for Income, Expenses, Bills and Savings. A red Expenses bar means you went over.",
    help_dash_donut_p: "Hover or tap a slice to see the label and percentage. They show where your money comes from and where it runs off to.",
    help_dash_bottom_p: "Quick peeks at your Debt Payoff progress and Savings Goals.",
