    af_less_day: "{0} less each day until {1}. Fun.",
    af_tight_note: "Hope nothing unexpected happens",
    af_dip: "Buying now would raid your bill money. Great plan.",
    af_save_toward: "Or, wild idea, save for it: {0} a week for a month",
    af_foot: "Bills already due come first. Obviously.",
    tx_way_afford_sub: "See what a purchase does before you regret it",
    nl_bills_today: "+ {0} in bills, of course",
    pay_settled: "{0} {1} paid · already set aside, as planned ✓",
    pay_settled_part: "{0} {1} of {2} paid · already set aside ✓",
    pay_settled_over: "{0} paid · {1} more than planned. Naturally.",
    toast_undone: "Undone. As if it never happened.",
    nth_fix: "How to fix it (it is easy)",
    nth_aria: "What is this, and how do I fix it?",
    nth_bill_late_w: "This bill's due date has passed and, surprise, it is still not paid.",
    nth_bill_late_f: "If you paid it, tap Pay and log the date it went out | If not, pay it soon, late fees are not a hobby | If the amount or date changed, update the bill so reminders stop lying",
    nth_bill_soon_w: "This bill is due within the week. Just so you know.",
    nth_bill_soon_f: "Make sure the money is actually there before the due date | Tap Pay once it leaves your account | Paying another way? Log it here anyway so your figures make sense",
    nth_debt_late_w: "This debt's minimum payment date has passed and, shockingly, the full minimum is not logged.",
    nth_debt_late_f: "If you paid it, tap Pay and log the date it left your account | If not, pay at least the minimum now: fees and a bruised credit score are not a fun combo | Check the debt's due day is actually right",
    nth_debt_soon_w: "This debt's minimum is due within the week. Mark the calendar.",
    nth_debt_soon_f: "Make sure the minimum is covered before the due date | Tap Pay once it goes out | Paying more than the minimum clears it sooner, who knew",
    nth_over_w: "You have spent more here than you planned. Bold strategy.",
    nth_over_f: "Tap Review to see the category | Maybe stop spending on it until the period ends | If the amount was unrealistic, raise it and lower another so the plan still adds up",
    nth_uncat_w: "These expenses have no category, so your budget is just guessing. Great.",
    nth_uncat_f: "Tap Sort them to see them | Give each a category, it takes seconds | Your budget updates immediately",
    nth_goal_late_w: "This goal's date has passed and it did not reach its target. Classic.",
    nth_goal_late_f: "Tap Review to find the goal | Set a new date, or lower the target to what you actually saved | If you have given up, delete the goal",
    auto_badge_title: "Added automatically on this date, you are welcome. Pay it now to settle it early or by hand.",
