    layout_coming_soon: "More coming soon. Allegedly.",
    changes_autosaved: "✅ Changes are saved automatically. No button needed, relax.",
    rollover_desc: "Carry unspent money from last period into this one. If there is any.",
    rollover_autocarry_label: "Auto-carry from previous period",
