    bud_due_date_hint: "When this is due each period. It shows on the Smart Calendar, so you cannot claim you forgot.",
    help_bud_intro: "The Budget tab is where you plan your money, before reality happens. Set expected amounts per category and the actuals fill in from your Transactions. Bills and savings goals have their own tabs.",
