    ch_set_err_order: "The highest amount must be more than the lowest. That is what highest means.",
    ch_set_err_cap: "The highest amount can be at most {0}. Let's not get carried away.",
    ch_desc: "Small games for the moment you are about to spend. When the money wins, it goes to a goal or debt instead of that thing you did not need.",
    ch_cat_decide_desc: "Torn between two choices? Let a game decide, since you cannot.",
    ch_hist_empty: "Nothing played yet. Scared?",
