    help_sett_penny_p: "Enable Ezzo below. \"How to create my key\" for setup.",
    help_penny_intro: "Ezzo talks from your browser to Google with your free Gemini API key. No Ezzo Budget server exists.",
    help_penny_step1: "Sign in at Google AI Studio (aistudio.google.com/apikey).",
    help_penny_step2: "\"Create API key\" (or \"Create key in new project\").",
    help_penny_step3: "Copy the key.",
    help_penny_step4: "Paste into \"Gemini API Key\", click \"Save key\".",
    help_penny_cost_p: "Free tier, Google's limits (check aistudio.google.com). The \"questions asked\" counter is local, not your quota.",
    help_penny_safety_p: "Encrypted in your browser; sent only to Google's API. Never to an Ezzo Budget server.",
    guide_welcome_big: "Income and spending tracking, debt payoff, savings goals, calendar, subscriptions and Ezzo, the AI assistant. Start with the Dashboard.",
    guide_dashboard_big: "Everything important, one screen.",
    guide_dashboard_step1: "Top cards: <strong>Total Income</strong>, <strong>Total Outgoing</strong>, <strong>Savings Rate</strong>, <strong>Net Leftover</strong>.",
    guide_dashboard_step2: "<strong>Upcoming</strong>: everything due in 7 days.",
    guide_dashboard_step3: "<strong>Debt Payoff</strong> and <strong>Savings Goals</strong> show progress.",
    guide_dashboard_connect1: "All numbers are live from the other pages.",
    guide_dashboard_connect2: "Net Leftover includes <strong>Rollover</strong>.",
    guide_dashboard_connect3: "Wrong number? Check its source page.",
    guide_dashboard_tip: "Scan daily, 30 seconds, catch bills early.",
    guide_dashboard_usecase_p: "<p><strong>Maria</strong> sees $420 Net Leftover on payday and tops up her emergency fund.</p><p>Over on Dining, she skips takeout.</p>",
    guide_transactions_big: "Transactions power everything. Nothing is added for you.",
    guide_transactions_step1: "<strong>Add Transaction</strong>: type, category, amount.",
    guide_transactions_step2: "<strong>Pay</strong> in Coming up: one tap.",
    guide_transactions_step3: "<strong>Import CSV</strong> for bulk data.",
    guide_transactions_step4: "Tap to edit; filter to find.",
    guide_transactions_connect1: "Log: paid. Delete: owed. Free to spend stays accurate.",
    guide_transactions_connect2: "Transactions count toward categories automatically.",
    guide_transactions_connect3: "Dashboard is built from this.",
    guide_transactions_tip: "Log when paid, not when due.",
    guide_transactions_usecase_p: "<p><strong>Jack</strong> logs Netflix via <strong>+ Add Transaction</strong>, Expense → Entertainment.</p><p>He clears duplicates with <strong>Delete Selected</strong>.</p>",
    guide_budget_big: "Targets for Income, Expenses, Bills, Savings on one screen.",
    guide_budget_step1: "Add to <strong>Income</strong>, <strong>Expenses</strong>, <strong>Bills</strong>, <strong>Savings</strong>; set <strong>Expected</strong>.",
    guide_budget_step2: "<strong>Actual</strong> fills in as you log.",
    guide_budget_step3: "Compare Expected vs Actual.",
    guide_budget_step4: "Update Expected as life changes.",
    guide_budget_connect1: "Transactions flow into categories here.",
    guide_budget_connect2: "Spending Breakdown and Net Leftover use these.",
    guide_budget_connect3: "<strong>Allocation Buckets</strong> on? Targets show here.",
    guide_budget_tip: "Review monthly.",
    guide_budget_usecase_p: "<p><strong>Priya</strong> budgets $500 for Groceries; Actual fills in.</p><p>Orange bar: she eases off in time.</p>",
    guide_debt_big: "A debt-free plan: which debt first, interest saved.",
    guide_debt_step1: "Each debt: <strong>Balance</strong>, <strong>APR</strong> (interest rate), <strong>Minimum Payment</strong>.",
    guide_debt_step2: "<strong>Snowball</strong> (smallest first) or <strong>Avalanche</strong> (highest rate first).",
    guide_debt_step3: "Extra goes to the strategy's first debt.",
    guide_debt_step4: "See your <strong>debt-free date</strong> and interest.",
    guide_debt_step5: "Loans: <strong>Loan term</strong> + <strong>Auto-calculate</strong>. Cards: <strong>% of balance</strong>.",
    guide_debt_step6: "<strong>declining payments</strong>: fixed principal. Set <strong>Repayment style</strong>.",
    guide_debt_step7: "ARM: <strong>Rate type</strong> \"Adjusts after a fixed period\". Escrow: <strong>Escrow type</strong> \"Declining with balance\".",
    guide_debt_step8: "<strong>ℹ️ info icon</strong>: schedule. <strong>Extra/mo</strong>: target one debt.",
    guide_debt_connect1: "Logged payments reduce balances.",
    guide_debt_connect2: "Snapshot on the Dashboard.",
    guide_debt_connect3: "Above-minimum payments shorten payoff most.",
    guide_debt_tip: "Snowball motivates; Avalanche saves more.",
    guide_debt_usecase_p: "<p><strong>Sam</strong> adds three debts, picks Avalanche.</p><p>A bonus goes in <strong>Extra/mo</strong>; the ℹ️ schedule shows the gain.</p>",
    guide_sinking_big: "Money set aside. Target and date give a monthly amount; no target makes a pot.",
    guide_sinking_step1: "Goal: <strong>Target Amount</strong>, optional date.",
    guide_sinking_step2: "Contribute; <strong>progress bar</strong> fills.",
    guide_sinking_step3: "At target: pay without touching the budget.",
    guide_sinking_connect1: "Goals are separate from everyday spending.",
    guide_sinking_connect2: "Progress on the Dashboard.",
    guide_sinking_connect3: "Regular small contributions prevent budget shocks.",
    guide_sinking_tip: "Use round monthly amounts, e.g. $50.",
    guide_sinking_usecase_p: "<p><strong>Elena</strong>: $1,200 by July, $150/month.</p><p>Each payday: <strong>Add contribution</strong>.</p>",
    guide_subscriptions_big: "All scheduled payments. Subscriptions are labelled bills.",
    guide_subscriptions_step1: "Each subscription: cost, frequency (monthly, yearly, etc.).",
    guide_subscriptions_step2: "See the <strong>Monthly Cost</strong> total.",
    guide_subscriptions_step3: "Pause or cancel unused ones.",
    guide_subscriptions_connect1: "Feeds Dashboard and Total Outgoing.",
    guide_subscriptions_connect2: "Dates also on the Calendar.",
    guide_subscriptions_connect3: "Review every few months to find leaks.",
    guide_subscriptions_tip: "Review monthly with your statement.",
    guide_subscriptions_usecase_p: "<p><strong>Jack</strong> adds Netflix, $15.49, Monthly; taps <strong>Pay</strong> when charged.</p><p>Price rises to $17.99; a ↑ marks it.</p>",
    guide_calendar_big: "Everything money-related, one month view.",
    guide_calendar_step1: "Dots mark what's due each day.",
    guide_calendar_step2: "Tap a day for details.",
    guide_calendar_step3: "Check before big purchases.",
    guide_calendar_connect1: "Data comes from other pages; the Calendar stores none.",
    guide_calendar_connect2: "Spots crowded weeks early.",
    guide_calendar_connect3: "View only; safe to browse.",
    guide_calendar_tip: "Check weekly.",
    guide_calendar_usecase_p: "<p><strong>Amir</strong> spots an unpaid bill due Monday.</p><p>He pays and logs $87.40 from the calendar.</p>",
    guide_rollover_big: "Unspent money carries forward.",
    guide_rollover_step1: "<strong>Settings</strong> → <strong>Rollover</strong>.",
    guide_rollover_step2: "Turn it on.",
    guide_rollover_step3: "Net Leftover includes it.",
    guide_rollover_connect1: "Uses last period's Net Leftover.",
    guide_rollover_connect2: "Unlike goals, Rollover just tracks existing money.",
    guide_rollover_connect3: "Good months compound.",
    guide_rollover_tip: "Move big rollovers into a goal.",
    guide_rollover_usecase_p: "<p><strong>Noor</strong>'s $180 June leftover rolls into July via <strong>Auto-carry</strong>.</p>",
    guide_automation_big: "Posts recurring rules automatically.",
    guide_automation_step1: "<strong>Settings</strong> → <strong>Automation</strong>.",
    guide_automation_step2: "Turn it on.",
    guide_automation_step3: "Verify in Transactions.",
