    guide_automation_connect3: "Keeps the app current.",
    guide_automation_tip: "Enable once rules are accurate.",
    guide_automation_usecase_p: "<p><strong>Tom</strong> uses <strong>Automate</strong> for three monthly payments.</p><p>They log themselves each period.</p>",
    guide_penny_big: "Built-in AI assistant; answers from your real data, with charts.",
    guide_penny_step1: "<strong>Settings</strong>: enable Ezzo, paste a Gemini API key.",
    guide_penny_step2: "Tap the sparkle icon.",
