    dash_no_sinking: "No savings goals yet.",
    help_dash_intro: "The Dashboard gives you a calm, real-time view of your finances. Every number updates as you log transactions.",
    help_dash_hero_p: "The big figure is what you can still spend this period: what has come in, less what has gone out, less everything still owed before the period ends. Beside it, Coming up lists the next five payments still owed, overdue bills first. Press Pay on any to log it.",
    help_dash_leftover_p: "White means you are on track. Red means what you still owe is more than what remains.",
    help_dash_cashflow_p: "Each row shows Expected (grey bar) beside Actual (coloured bar) for Income, Expenses, Bills and Savings. A red Expenses bar means spending went past the budget.",
    help_dash_donut_p: "Hover or tap a segment to see the label and percentage. These show where your money comes from and where it flows.",
    help_dash_bottom_p: "Quick snapshots of your Debt Payoff progress and your Savings Goals.",
    help_dash_tip: "💡 Click the date badge at the top to change your budget period.",
