    dash_compare_no_data: "No previous period data",
    recurring_desc: "Set up transactions that repeat on a schedule (example: rent, salary or subscriptions). They are added to your list on each due date.",
    recurring_empty: "No automatic transactions added yet.",
    recurring_generated: "{0} new transactions added",
