    dpc_snowball_desc: "Lowest balance first: quick wins keep you motivated!",
    dpc_avalanche_desc: "Highest rate first: saves the most money overall!",
    dpc_extra_hint: "Amount above your minimum payments to throw at debt each month!",
    dpc_empty_title: "No debts added yet!",
    dpc_empty_sub: "Click “+ Add debt” to build your payoff plan!",
    dpc_name_hint: "The label you'll see for this debt everywhere in the app.",
    dpc_type_hint: "Used to apply the right rules for this kind of loan (e.g. mortgages support escrow and ARM rates).",
    dpc_balance_hint: "The amount you currently owe on this debt.",
    dpc_apr_hint: "The annual interest rate charged on the remaining balance.",
    dpc_min_hint: "The smallest payment required each month, before any extra you add.",
    dpc_term_hint: "Sets how long this loan runs, so Auto-calculate can work out an accurate minimum payment.",
    dpc_min_mode_hint: "Fixed keeps the same minimum every month. Percent of balance recalculates it as the balance shrinks, common for credit cards.",
    dpc_min_percent_hint: "The percentage of the remaining balance used to calculate the minimum payment.",
    dpc_min_floor_hint: "The minimum payment never drops below this amount, even if the percentage works out lower.",
