    dpc_focus_hint: "Where your extra money is aimed, in order",
    dpc_payoff_order_av: "Payoff order: 🌊 Avalanche (highest rate first)",
    help_dpc_intro: "This calculator builds a personalised plan to get you debt-free, based on your debts and chosen strategy!",
    help_dpc_balance_li: "Balance - How much you currently owe on that debt (for now).",
    help_dpc_apr_li: "APR % - The annual interest rate (it's on your statement). E.g. 18.9 means 18.9%.",
    help_dpc_min_li: "Min. payment - The minimum monthly payment required by the lender.",
    help_dpc_due_li: "Due day - The day of the month the payment is due (shows on the Smart Calendar).",
    help_dpc_snowball_li: "⛄ Snowball - Pay the smallest balance first, then roll that payment into the next. Best for motivation!",
    help_dpc_avalanche_li: "🌊 Avalanche - Pay the highest interest rate first. Saves the most money overall!",
    help_dpc_extra_p: "Any surplus above your minimums can go at debt. Even a small extra payment can save hundreds in interest and cut months off your timeline! Results update as you type.",
    help_dpc_tip: "💡 Toggle between methods to see how much interest you'd save with each approach!",
    help_dpc_term_li: "Loan term - For mortgages, student, car and personal loans, set the term in years and click Auto-calculate to work out an accurate minimum payment.",
    help_dpc_percent_li: "Percentage-based minimum - For credit cards, switch to \"% of balance\" to match how your statement's minimum payment actually works (e.g. 2% of balance or $25, whichever is higher).",
    help_dpc_escrow_li: "Escrow - For mortgages, add your monthly taxes and insurance so your real monthly cost is accurate everywhere; it's excluded from the payoff projection since it doesn't reduce your balance.",
    help_dpc_amort_li: "Repayment style - Equal payments keep your payment the same every month. Declining payments (equal principal) keep the principal part fixed, so your total payment shrinks over time; check your loan documents to see which one you have.",
    help_dpc_escrow_mode_li: "Escrow type - choose \"Declining with balance\" if your escrow shrinks along with your loan balance, like some declining insurance premiums; you can watch it decline in the payment schedule.",
    help_dpc_rate_type_li: "Rate type - choose \"Adjusts after a fixed period\" for ARMs, then set how many years the rate is fixed and what it changes to afterward.",
    help_dpc_extra_targeted_li: "Extra/mo (per debt) - an optional amount paid only toward that one debt every month, on top of its minimum, regardless of your snowball/avalanche order.",
    dsched_never_payoff_warning: "At this pace, this debt won't be fully paid off within 50 years, but that's fixable! A higher minimum, a higher percentage floor, or an extra payment will get it moving.",
